    Ok(match self.chars.peek() {
        Some(&c) => match c {
            '.' => Some(self.scan_symbol()).into(),
            '=' => Some(self.scan_symbol()).into(),
            '!' => {
                if self.next_is('<') {
                    Some(Token::NotEqual).into()
                } else {
                    Some(self.scan_symbol()).into()
                }
            }
            '>' => {
                if self.next_is('=') {
                    Some(Token::GreaterThanOrEqual).into()
